import urllib.request
from html.parser import HTMLParser
class Links(HTMLParser):
 def handle_starttag(self, tag, attrs):
  if tag == 'a':
   href = dict(attrs).get('href', '')
   if 'support.google.com' in href:
    print(href)
url = 'https://workspace.google.com/blog/ai-and-machine-learning/enterprise-security-controls-google-workspace-gemini'
Links().feed(urllib.request.urlopen(url).read().decode())
